"""Regenerate ONTOLOGY_METHODS.md from code, without accessing providers."""
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from ioc_hunter.methods import list_candidates, list_runnable_methods
from ioc_hunter.ontology import EDGES


def render_catalogue() -> str:
    implemented, candidates = list_runnable_methods(), list_candidates()
    lines = [
        "# Ontology and directed method catalogue", "",
        "Generated by `python tools/generate_catalogue.py`. Do not edit the tables manually.", "",
        f"**{len(implemented)} implemented methods; {len(candidates)} disabled research candidates.**", "",
        "A method is `(source, input type, output type)`. IOC edges are undirected; retrieval methods are directional.",
        "Figure 3 membership is strict. Baseline `no` denotes documented IPv6 additions beyond Table I.", "",
        "Implementation, configuration and live verification are separate:", "",
        "- Implemented: a provider adapter and parser exist.",
        "- Configured: local credentials/dependencies are present; this does not prove source access.",
        "- Live verified: a particular method was tested at a recorded time; this is not a current availability guarantee.",
        "- Candidate: not implemented; its retrieval route is unconfirmed, even if the type pair fits the ontology.", "",
        "Use `python -m ioc_hunter methods --implemented --availability` to inspect local configuration without network calls.", "",
        "Historical live checks on 10 October 2026: RapidDNS domain-to-IPv4 and VirusTotal domain-to-IPv4 returned partial results; OTX domain-to-IPv4 returned a loading page. Other routes are not live-verified. See LOOKUP_FOUNDATION.md.", "",
        "## All Figure 3 type connections", "",
        "| Left | Right | Figure label | Category |", "| --- | --- | --- | --- |",
    ]
    lines.extend(f"| {e.left} | {e.right} | {e.label} | {e.category} |" for e in EDGES)
    lines += ["", "## Implemented provider methods", "",
              "Definitions live in the corresponding `ioc_hunter/providers/<source>.py` module.", "",
              "| Method ID | Input | Output | Operation | Baseline |",
              "| --- | --- | --- | --- | --- |"]
    lines.extend(f"| `{m.id}` | {m.input_type} | {m.output_type} | {m.operation} | {'yes' if m.baseline else 'no'} |" for m in implemented)
    lines += ["", "## Disabled research candidates", "",
              "`no_verified_lookup` means **not implemented / retrieval route unconfirmed**. It does not mean a provider returned no results or definitely cannot support the lookup. Candidates are excluded from runnable discovery.", "",
              "| Method ID | Input | Output | Status |", "| --- | --- | --- | --- |"]
    lines.extend(f"| `{m.id}` | {m.input_type} | {m.output_type} | Not implemented / retrieval route unconfirmed |" for m in candidates)
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    (ROOT / "ONTOLOGY_METHODS.md").write_text(render_catalogue(), encoding="utf-8")
    print("Updated ONTOLOGY_METHODS.md")
